# Spreadsheet template guides (search-intent pages for the Gumroad templates). Exec'd from build.py after guides.py.
GUM='https://goudastudios.gumroad.com/l/'
SG=[
 dict(slug='credit-card-benefits-tracker-spreadsheet',prod='uurml',pname='Credit Card Benefits Tracker Spreadsheet',price='3.99',
  q='Credit card benefits tracker spreadsheet: how to track statement credits and annual fees',
  d='How to build a credit card benefits tracker in Google Sheets or Excel: the columns to use, copy-paste formulas for monthly, quarterly and semiannual credit resets, and a simple keep or cancel test for each annual fee card.',
  a='List every statement credit as its own row with its card, value, reset cadence, amount used and next reset date. Add one formula for the reset date, one for the amount left, and a conditional format that turns a row red when unused value expires within 14 days. Then total the credits you actually used per card and subtract the annual fee to see if the card pays for itself.',
  secs=[
   ('Why credits go unused','Premium cards bundle many small credits (rideshare, dining, streaming, airline fees, travel, Global Entry or TSA PreCheck) that reset on different schedules. Some reset on the calendar month, some each quarter, some twice a year, and some on your cardmember year. Nobody remembers all of them, so the fix is a single list with the next deadline next to each credit.',None),
   ('Columns to use','One row per credit, not per card. That way each credit has its own deadline.',['Card','Credit (for example "Dining credit")','Value per period ($)','Cadence: Monthly, Quarterly, Semiannual or Annual','Used this period ($)','Left this period = Value minus Used','Next reset date (formula below)','Days to reset = Next reset minus TODAY()','Annual value = Value x periods per year','Notes (how to trigger it, which merchants count)']),
   ('Copy-paste reset date formulas','These work in both Google Sheets and Excel. Use whichever matches the credit\'s cadence, or combine them with IF on the cadence column.',['Monthly (resets on the 1st): =EOMONTH(TODAY(),0)+1','Quarterly (Jan, Apr, Jul, Oct): =EOMONTH(DATE(YEAR(TODAY()),CEILING(MONTH(TODAY())/3,1)*3,1),0)+1','Semiannual (Jan and Jul): =IF(MONTH(TODAY())<=6,DATE(YEAR(TODAY()),7,1),DATE(YEAR(TODAY())+1,1,1))','Annual on the calendar year: =DATE(YEAR(TODAY())+1,1,1)','Annual on your cardmember year (account open date in K2): =EDATE(K2,12*(DATEDIF(K2,TODAY(),"y")+1))']),
   ('Make expiring credits turn red','Select the data rows, add a conditional formatting rule with a custom formula, and pick a red fill. With Left in column F and Next reset in column G the rule is: =AND($F2>0,$G2-TODAY()<=14). Anything with money still on it and two weeks or less to go stands out.',None),
   ('Does the card pay for itself?','Add a small summary table with one row per card. Benefits used = SUMIFS of the Used column for that card over the year. Net value = Benefits used minus Annual fee. AF covered % = Benefits used divided by Annual fee. Over 100% means the card earns its fee from credits alone. Under 100% means the points and perks have to make up the gap, and it may be time to ask about a retention offer or a downgrade before the fee posts.',None),
   ('Never get surprised by an annual fee','Keep each card\'s fee date in its own column and add Days until fee = FeeDate minus TODAY(). Sort by it, or filter for anything under 60 days, so you can decide to keep, downgrade or cancel before the charge lands.',None),
  ],
  faq=[('Is there a free credit card benefits tracker?','Yes, you can build one in about 15 minutes with the columns and formulas on this page. If you would rather not build it, the ready-made template below includes the reset logic, red alerts, a per-card value dashboard and a fee calendar.'),('Should I track credits by card or by credit?','By credit. Each credit has its own value and reset schedule, so one row per credit is the only way to show the right deadline. Roll it up by card in a summary table.'),('Does this work in Excel and Google Sheets?','Yes. EOMONTH, EDATE, CEILING, DATEDIF and SUMIFS work in both.'),('Do I need to connect my bank?','No. A spreadsheet tracker needs no logins or bank connections. You just tick off a credit when you use it.')]),
 dict(slug='credit-card-churning-spreadsheet-template',prod='xjmqe',pname='Credit Card Churning Tracker Spreadsheet',price='4.49',
  q='Credit card churning spreadsheet template: track bonuses, minimum spend and your x/24 count',
  d='How to set up a credit card churning spreadsheet in Google Sheets or Excel: the application log columns, formulas for minimum spend remaining and deadlines, a rolling 24-month card counter and points valuation.',
  a='Keep one row per application with the date, issuer, personal or business, status, bonus, minimum spend, spend so far and deadline. Formulas then show spend remaining and days left, a COUNTIFS gives your rolling 24-month personal card count, and a MINIFS tells you when the oldest card drops out of the window.',
  secs=[
   ('Columns for the application log','The formulas below assume this layout. Extra columns (issuer, rewards program, annual fee, fee date, bonus posted) can go after column J.',['A: Application date','B: Card','C: Personal or Business','D: Status (Pending, Approved, Denied, Closed)','E: Bonus (points or miles)','F: Minimum spend','G: Spend so far','H: Spend deadline','I: Spend remaining: =MAX(0,F2-G2)','J: Days left: =H2-TODAY()']),
   ('Spend deadline formulas','Many offers give you about 3 months to hit the minimum spend, but terms vary, so always use the date in your own offer. If the window is 3 months from the date in A2, put =EDATE(A2,3) in H2. Then add a conditional format rule with the custom formula =AND($I2>0,$J2<=14) and a red fill, which flags any card that still needs spend and has two weeks or less.',None),
   ('Rolling 24-month card counter','Some issuers are widely reported to limit approvals by how many personal cards you opened in the last 24 months (the community calls this x/24, for example 5/24). Issuers do not publish all of their rules, so treat the limit as a number you set yourself. Using the layout above:',['Cards in window: =COUNTIFS(A:A,">="&EDATE(TODAY(),-24),C:C,"Personal",D:D,"Approved")','Slots left (limit in cell M1): =M1-[cards in window]','Next drop-off date: =EDATE(MINIFS(A:A,A:A,">="&EDATE(TODAY(),-24),C:C,"Personal",D:D,"Approved"),24)']),
   ('Per-issuer cooldowns','Add a small table with one row per issuer: last application date (=MAXIFS on the log), applications in the last 12 months (COUNTIFS with EDATE(TODAY(),-12)), and a cooldown in days you enter yourself. Next eligible = last application + cooldown, and OK to apply = IF(TODAY()>=next eligible,"OK","Wait").',None),
   ('Value your points','Keep a balances tab with each program and your own cents-per-point estimate. Bonus value in dollars = Bonus points x cents per point / 100. Summing that across approved cards gives you what churning actually earned you this year, which helps when you weigh annual fees.',None),
  ],
  faq=[('Is there a churning spreadsheet template for Google Sheets?','Yes. You can build the core of one with the formulas on this page. The ready-made template below adds a deadline-sorted dashboard, issuer rule cells, a points balance tab and the x/24 counter, and works in Google Sheets and Excel.'),('Does the spreadsheet know each bank\'s rules?','No spreadsheet should hard-code them, because issuers change rules and do not publish all of them. Keep every rule as a cell you can edit when new data points appear.'),('Does churning hurt my credit score?','Each application usually adds a hard inquiry and a new account lowers your average account age, which can lower your score for a while. Paying in full every month matters far more. This is general information, not financial advice.')]),
 dict(slug='rental-property-analysis-spreadsheet',prod='pcoxn',pname='Rental Property Investment Analyzer Spreadsheet',price='6.99',
  q='Rental property analysis spreadsheet: cash flow, cap rate and cash-on-cash return formulas',
  d='How to analyze a rental property in Google Sheets or Excel: the inputs, the mortgage, NOI, cap rate, cash flow, cash-on-cash and break-even rent formulas, and a worked example with real numbers.',
  a='Enter the price, deposit, loan rate and term, rent, vacancy and every operating expense. Net operating income (NOI) is effective rent minus operating expenses. Cash flow is NOI minus the mortgage. Cap rate is NOI divided by price, and cash-on-cash return is yearly cash flow divided by the cash you put in.',
  secs=[
   ('Inputs',None,['Purchase price, deposit (down payment) % and closing costs','Interest rate, loan term in years, principal and interest or interest only','Rent per month (or per week x 52 / 12 in NZ, AU and the UK)','Vacancy %, property management % of collected rent','Property tax or council rates, insurance, maintenance %, HOA or body corporate fees']),
   ('Core formulas (Google Sheets and Excel)',None,['Loan = Price x (1 minus Deposit %)','Monthly mortgage (principal and interest): =PMT(Rate/12, Years*12, -Loan)','Interest-only payment: =Loan*Rate/12','Effective rent = Annual rent x (1 minus Vacancy %)','Operating expenses = management + tax + insurance + maintenance + HOA (not the mortgage)','NOI = Effective rent minus Operating expenses','Cap rate = NOI / Price','Annual cash flow = NOI minus 12 x Monthly mortgage','Cash-on-cash return = Annual cash flow / (Deposit + Closing costs + Repairs)','DSCR = NOI / Annual mortgage payments','Gross yield = Annual rent / Price']),
   ('Worked example','A $300,000 house, 20% down ($60,000) plus $9,000 closing costs, a $240,000 loan at 7% over 30 years, rent of $2,400 a month, 5% vacancy, 8% management, $3,600 property tax, $1,500 insurance and maintenance at 5% of rent.',['Mortgage: =PMT(0.07/12,360,-240000) = $1,596.73 a month, or $19,160.71 a year','Effective rent: $28,800 minus 5% = $27,360','Operating expenses: $2,188.80 management + $3,600 tax + $1,500 insurance + $1,440 maintenance = $8,728.80','NOI: $18,631.20, so the cap rate is 6.2%','Cash flow: $18,631.20 minus $19,160.71 = about minus $530 a year','Cash-on-cash: about minus 0.8% on $69,000 invested, and DSCR is 0.97','Break-even rent: about $2,454 a month']),
   ('What the example tells you','The house looks fine on gross yield (9.6%) and comes close to the 1% rule screen ($2,400 is 0.8% of the price), but at 7% interest it loses a little money every month. Quick rules like the 1% rule and the 50% rule are only screens. The full NOI and cash flow math is what tells you whether a deal works, and a 10-year projection shows whether appreciation and loan paydown make up for thin cash flow.',None),
   ('Compare more than one property','Put each property in its own column with the same rows, then highlight the best value in each row. Side by side, it is easy to see that a cheaper property with lower rent can still beat a nicer one on cash-on-cash return.',None),
  ],
  faq=[('What is a good cap rate?','It depends on the market and property type. Lower cap rates are common in expensive, low-risk areas and higher ones in cheaper or riskier areas. Compare against similar properties nearby rather than one fixed number.'),('Does this work outside the US?','Yes. The formulas are the same anywhere. Use your own currency, enter weekly rent x 52 / 12 if rent is quoted weekly, and include council rates or body corporate fees as expenses.'),('Should I include the mortgage in NOI?','No. NOI excludes financing, which is why it is used for cap rate. Cash flow is the number after the mortgage.'),('Is this financial advice?','No. It is an estimating method. Check numbers with a lender, accountant or local agent before buying.')]),
 dict(slug='christmas-gift-tracker-spreadsheet',prod='xmas-gift-tracker',pname='Christmas Gift Tracker and Holiday Budget Spreadsheet',price='2.99',
  q='Christmas gift tracker spreadsheet: track gifts and a per-person budget in Google Sheets or Excel',
  d='How to set up a Christmas gift tracker in Google Sheets or Excel: the columns, a per-person budget with SUMIFS, over-budget alerts, a days-until-Christmas counter and a list of who still needs a gift.',
  a='Make one tab listing each person and their gift budget, and a second tab with one row per gift (who it is for, the gift, price and status). A SUMIFS on the gift tab gives each person\'s spent total, budget minus spent gives what is left, and a conditional format turns anyone over budget red.',
  secs=[
   ('Two tabs are enough to start','Keep people and gifts apart. One person can get several gifts, so the gift list needs its own row per item and the people tab rolls it up.',['People tab: A Name, B Budget, C Spent, D Left, E Status','Gifts tab: A For (who), B Gift, C Store or link, D Price, E Status (Idea, Ordered, Bought, Wrapped, Given)']),
   ('Formulas for the people tab','These work in both Google Sheets and Excel. Put them in row 2 and fill down.',['Spent: =SUMIFS(Gifts!D:D,Gifts!A:A,A2)','Left: =B2-C2','Status: =IF(C2=0,"Needs a gift",IF(C2>B2,"Over budget","OK"))','Total budget: =SUM(B:B)','Total spent: =SUM(C:C)']),
   ('Make overspending obvious','Select the people rows, add a conditional formatting rule with a custom formula, and choose a red fill. With Budget in B and Spent in C the rule is =$C2>$B2. Add a second rule with =$C2=0 and a yellow fill so the people you have not shopped for yet stand out.',None),
   ('Countdown and progress','A countdown keeps the deadline in view and a simple progress count shows how far along you are.',['Days until Christmas: =DATE(2026,12,25)-TODAY()','Gifts bought or later: =COUNTIF(Gifts!E:E,"Bought")+COUNTIF(Gifts!E:E,"Wrapped")+COUNTIF(Gifts!E:E,"Given")','Share of gift budget used: =SUM(C:C)/SUM(B:B)']),
   ('Use dropdowns so the math never breaks','In the Gifts tab, make column A a dropdown that pulls from the names on the People tab, and column E a dropdown with the five status values. Typos like "Mum" vs "Mom" are what usually break a SUMIFS, and a dropdown stops them.',None),
   ('Track the rest of the holiday budget too','Gifts are usually only part of holiday spending. Add a budget tab with planned and actual amounts for food, decorations, travel, cards and postage, and parties, plus an expense log whose category column feeds the actual column with SUMIFS. Then you can see the whole season, not just presents.',None),
  ],
  faq=[('Is there a free Christmas gift tracker for Google Sheets?','Yes. You can build the core of one in about 10 minutes with the columns and formulas on this page. The ready-made template below adds a dashboard with a chart, a 300 row gift list with dropdowns, a holiday budget, an expense log, a card list, stocking stuffers, a meal plan and an 8 week countdown.'),('Does it work in Excel too?','Yes. SUMIFS, COUNTIF, TODAY and DATE work in both Excel and Google Sheets.'),('Should I set a budget per person or one total?','Both. A per-person budget stops one gift from blowing the plan, and the total tells you whether the season as a whole is on track.')]),
 dict(slug='christmas-dinner-planner-timeline',prod='xmas-dinner-planner',pname='Christmas Dinner Planner Printable',price='1.49',fmt='11 page PDF, US Letter + A4',fmt2='print at home or use on a tablet',
  q='Christmas dinner planner: how to make a cooking timeline so everything is ready at once',
  d='How to plan Christmas dinner: build the menu, a guest list with dietary notes, one shopping list, and a backwards cooking timeline from your serving time so every dish lands hot together.',
  a='Pick your serving time first, then work backwards. For each dish write its cook time, rest time and oven temperature, subtract them from the serving time to get its start time, and sort the list by start time. Anything that needs the oven at a different temperature at the same time is a clash to fix before the day.',
  secs=[
   ('Start with the menu and the guest list','Write every dish under starters, mains, sides, desserts and drinks, and next to each guest note any allergies or diets and what they are bringing. This tells you how many portions you need and stops two people bringing the same dessert.',None),
   ('One shopping list, sorted by section','Go through each recipe and copy every ingredient onto a single list grouped by store section (produce, meat, dairy, bakery, pantry, drinks). Mark items that keep, like pantry goods and drinks, to buy early, and leave fresh produce for the last few days.',None),
   ('Build the timeline backwards','For each dish, list the minutes it needs to cook and to rest. Start time = Serving time minus Cook time minus Rest time. If you keep it in a spreadsheet with the serving time in B1 and minutes in columns C and D, the start time for row 3 is:',['=$B$1-(C3+D3)/1440']),
   ('Check the oven','Write each dish\'s oven temperature next to its start and end times. If two dishes need the oven at different temperatures in the same window, move one to the hob, slow cooker or microwave, or cook it earlier and reheat it while the roast rests. The resting time of a large roast is usually the best window for roasting vegetables and heating sides.',None),
   ('Food safety','Use a meat thermometer rather than the clock alone. The USDA says turkey and other poultry are safe at an internal temperature of 165 degrees F, measured in the thickest part of the breast, the innermost part of the thigh and the innermost part of the wing. Check the cooking time chart for your bird\'s weight and allow extra time if it is stuffed.',None),
   ('The day before','Most of the prep can happen on Christmas Eve: peel and chop vegetables, make sauces and desserts, set the table, and check that the bird has fully thawed. Leaving only cooking and carving for the day itself is what makes it feel easy.',None),
  ],
  faq=[('How far ahead should I plan Christmas dinner?','About two to three weeks for the menu, guest list and ordering a bird or meat, then a final shopping trip two or three days before.'),('Is there a printable Christmas dinner planner?','Yes. The printable below has 11 pages: a menu planner, guest list with dietary notes, shopping list by section, a Christmas Day cooking timeline, a baking plan, a party planner, and house prep and table setting checklists, in US Letter and A4.'),('How long does a turkey take to thaw in the fridge?','The USDA guideline is about 24 hours for every 4 to 5 pounds, so start early for a large bird.')]),
 dict(slug='holiday-budget-planner-template',prod='xmas-bundle',pname='Christmas Planner Bundle (gift tracker spreadsheet, 25 page printable planner and dinner planner)',price='4.99',fmt='spreadsheet for Google Sheets + Excel plus printable PDFs',fmt2='5 files',
  q='Holiday budget planner template: how to plan Christmas spending and stick to it',
  d='How to make a holiday budget: the categories to include, a planned vs actual table with SUMIFS formulas, an expense log, and a weekly check-in so Christmas spending stays on plan.',
  a='List every holiday spending category (gifts, food, decorations, travel, cards and postage, parties, charity), give each a planned amount that adds up to a total you can afford, then log every purchase with a category. SUMIFS turns the log into an actual column, and actual minus planned shows where you are over.',
  secs=[
   ('Categories to include','People usually budget for gifts and forget the rest. Include all of these, even if some are small:',['Gifts (rolled up from a per-person list)','Food and drink, including Christmas dinner and parties you host','Decorations and the tree','Travel and gas','Cards, wrapping paper and postage','Clothes for events, teacher and coworker gifts, tips','Charity and donations']),
   ('Planned vs actual table','Make a Budget tab with Category in A, Planned in B, Actual in C and Difference in D, and an Expense Log tab with Date in A, Item in B, Category in C and Amount in D.',['Actual: =SUMIFS(\'Expense Log\'!D:D,\'Expense Log\'!C:C,A2)','Difference: =B2-C2','Total planned: =SUM(B:B)','Total actual: =SUM(C:C)']),
   ('Flag overspending','Add a conditional format with the custom formula =$C2>$B2 and a red fill on the budget rows. Make the Category column on the log a dropdown that pulls from the budget categories so every purchase lands in the right row.',None),
   ('Pick the total first','Decide the total you can afford from savings or this month\'s spare cash before you split it into categories. Splitting first and adding up later is how budgets drift. If you pay with a card, include the amount in your plan only if you can pay it off in full when the statement arrives.',None),
   ('A five minute weekly check','Once a week from November, add any purchases to the log and glance at the Difference column. Moving money between categories is fine as long as the total stays put.',None),
  ],
  faq=[('Is there a free holiday budget template?','Yes. The table and formulas on this page are a working template you can copy into Google Sheets or Excel. The bundle below includes a ready-made gift tracker and holiday budget spreadsheet plus a 25 page printable Christmas planner and an 11 page dinner planner.'),('How much should I budget for Christmas?','That depends on your income and savings. A common approach is to set a total you can pay in cash or pay off in full, then work backwards to per-person gift amounts.'),('Is this financial advice?','No. It is a planning method, not financial advice.')]),
 dict(slug='christmas-countdown-checklist-printable',prod='xmas-planner',pname='Printable Christmas Planner 2026',price='2.49',fmt='25 page PDF, US Letter + A4',fmt2='print at home or use in GoodNotes or Notability',
  q='Christmas countdown checklist: an 8 week plan to get ready for Christmas without the last minute rush',
  d='A week by week Christmas countdown from late October to December 25: when to set the budget, write the gift list, order cards, book travel, shop, wrap, plan dinner and prep the house.',
  a='Work backwards from December 25 in eight weekly blocks. Do the planning jobs first (budget, gift list, card list, dates), the ordering and booking jobs next (gifts, cards, travel, the bird), and leave only wrapping, fresh food and cooking for the final week.',
  secs=[
   ('Week 8 (around October 30): set the plan','Decide the total you can spend, list everyone you are buying for with a budget each, and put the key dates on a calendar: parties, school events, travel days and the last shipping dates for the carriers you use.',None),
   ('Week 7 (around November 6): lists and early orders','Write the Christmas card list and check addresses. Start the gift list with ideas next to each name, and order anything personalised or handmade now because those take the longest.',None),
   ('Week 6 (around November 13): book and order','Book travel and any time off work. If you are hosting, decide the guest count and order the turkey or roast from the butcher. Order or buy Christmas cards and stamps.',None),
   ('Week 5 (around November 20): get ready for the sales','Go through the gift list and mark the items worth waiting for a sale on. Buy anything that is not likely to be discounted, and log each purchase as you go.',None),
   ('Week 4 (around November 27): Black Friday, cards and decorations','Black Friday is November 27, 2026 and Cyber Monday is November 30. Shop from your list and budget so the deals serve the plan. Then get the decorations up and write and post cards.',None),
   ('Week 3 (around December 4): finish shopping','Aim to have every gift bought or ordered by now so online orders arrive in time. Plan the Christmas dinner menu and write one shopping list for it, sorted by store section.',None),
   ('Week 2 (around December 11): wrap and ship','Wrap gifts as they arrive, post anything that has to travel, and buy the non-perishable food and drinks for Christmas.',None),
   ('Week 1 (December 18 to 25): fresh food and the big day','Buy fresh produce two or three days before, thaw the bird in the fridge in good time, do prep on Christmas Eve, and follow a cooking timeline on the day.',None),
   ('Track it in a spreadsheet if you prefer','If you would rather tick things off on your phone, put the tasks in column A, the target week in B and a checkbox in C. A progress figure keeps you honest:',['Tasks done: =COUNTIF(C:C,TRUE)','Share done: =COUNTIF(C:C,TRUE)/COUNTA(A2:A)','Days until Christmas: =DATE(2026,12,25)-TODAY()']),
  ],
  faq=[('When should I start planning for Christmas?','About eight weeks ahead, at the end of October, gives enough time to spread the spending and the jobs out. Starting later still works; just merge the early weeks.'),('Is there a printable Christmas countdown checklist?','Yes. The printable planner below includes an 8 week countdown checklist plus a holiday budget, spending logs, gift and card lists, November and December 2026 calendars, dinner and baking plans, advent activities and a packing list, 25 pages in US Letter and A4.'),('What should I do first?','Set the total budget and the gift list. Almost every other job depends on knowing who you are buying for and how much you can spend.')]),
 dict(slug='chase-5-24-tracker-spreadsheet',prod='xjmqe',pname='Credit Card Churning Tracker Spreadsheet',price='4.49',
  q='Chase 5/24 tracker spreadsheet: count your cards and see when you drop below 5/24',
  d='How to track your 5/24 status in Google Sheets or Excel: which accounts to log, a COUNTIFS formula for cards opened in the last 24 months, and a formula for the exact date your count drops.',
  a='Log every new personal card account with its open date. Count the ones opened in the last 24 months with COUNTIFS, then take the oldest open date inside the window and add 24 months to find when your count goes down by one. Below 5 is the number the churning community reports Chase looks for.',
  secs=[
   ('What 5/24 means','Data points shared by the churning community suggest Chase usually declines most of its cards if you have opened 5 or more personal credit cards from any bank in the past 24 months. Chase does not publish the rule, so treat it as a reported pattern and keep the limit as a cell you can change.',None),
   ('What to log','One row per account. Most data points say these are what to include and leave out, but check recent reports before relying on it.',['Usually counts: new personal credit cards from any issuer','Often reported to count: being added as an authorized user on someone else\'s card (some people ask Chase to exclude it on recon)','Usually does not count: most business cards that do not report to your personal credit report','Does not count: product changes, because no new account is opened']),
   ('Columns','Keep it simple so the formulas stay readable.',['A: Open date','B: Card','C: Personal or Business','D: Status (Approved, Denied, Closed)','E: Counts toward 5/24? (TRUE or FALSE)']),
   ('Formulas (Google Sheets and Excel)',None,['Cards in the last 24 months: =COUNTIFS(A:A,">="&EDATE(TODAY(),-24),E:E,TRUE,D:D,"<>Denied")','Your status as text: =[count]&"/24"','Under 5/24?: =IF([count]<5,"Under 5/24","At or over 5/24")','Next drop-off date: =EDATE(MINIFS(A:A,A:A,">="&EDATE(TODAY(),-24),E:E,TRUE),24)','Date you will be under 5/24 (count in F1): =IF(F1<5,TODAY(),EDATE(SMALL(FILTER(A2:A,A2:A>=EDATE(TODAY(),-24),E2:E=TRUE),F1-4),24))']),
   ('Plan your next applications','Once you know your drop-off dates, decide the order: if you want Chase cards, apply for them while you are under 5/24 and before cards from other banks push you over. A sorted list of drop-off dates shows exactly when each slot opens up.',None),
  ],
  faq=[('Do closed cards still count toward 5/24?','Most data points say yes, because the rule is reported to count accounts opened in the last 24 months, open or closed.'),('Does a denied application count?','No. A denial adds a hard inquiry but no new account, so it does not add to the count.'),('Is there a ready-made 5/24 tracker?','Yes. The churning template below has the 24-month counter, drop-off dates, bonus deadlines and an issuer rules table you can edit, for Google Sheets and Excel.'),('Is this financial advice?','No. Bank rules are unpublished and change. Use this to stay organised and check recent data points before applying.')]),
 dict(slug='amex-platinum-credits-tracker',prod='uurml',pname='Credit Card Benefits Tracker Spreadsheet',price='3.99',
  q='Amex Platinum credits tracker: a spreadsheet to use every monthly, quarterly and annual credit',
  d='How to track premium card statement credits like those on the Amex Platinum in Google Sheets or Excel: one row per credit, reset date formulas for each cadence, enrollment reminders and a fee coverage check.',
  a='Make one row per credit with its value, cadence (monthly, quarterly, semiannual or annual), whether it needs enrollment, the amount used and the next reset date. Reset formulas and a red alert for unused credits that expire within 14 days keep you from leaving money on the table, and a summary shows how much of the annual fee the credits cover.',
  secs=[
   ('Why a premium card needs a tracker','Cards like the Amex Platinum pack in many statement credits with different reset schedules, and several only work after you enroll or link a specific account. The amounts and the list change from time to time, so copy the current credits from your card\'s benefits page into the sheet rather than relying on a list online.',None),
   ('Columns','One row per credit:',['Credit name','Value per period ($)','Cadence: Monthly, Quarterly, Semiannual or Annual','Needs enrollment? and Enrolled? (checkboxes)','Used this period ($)','Left = Value minus Used','Next reset date','Days to reset = Next reset minus TODAY()','How to trigger it (which merchant or app)']),
   ('Reset date formulas',None,['Monthly: =EOMONTH(TODAY(),0)+1','Quarterly: =EOMONTH(DATE(YEAR(TODAY()),CEILING(MONTH(TODAY())/3,1)*3,1),0)+1','Semiannual (Jan and Jul): =IF(MONTH(TODAY())<=6,DATE(YEAR(TODAY()),7,1),DATE(YEAR(TODAY())+1,1,1))','Calendar year: =DATE(YEAR(TODAY())+1,1,1)']),
   ('Alerts that actually help','Add two conditional formatting rules. Red for money about to expire: =AND($F2>0,$H2-TODAY()<=14). Amber for credits you have not enrolled in yet: =AND($D2=TRUE,$E2=FALSE). Unenrolled credits are the easiest money to lose.',None),
   ('Does the card earn its fee?','Annual value of each credit = Value x periods per year. Total the amount you actually used this cardmember year with SUMIFS and divide by the annual fee. Count only credits you would have spent money on anyway, which gives an honest answer before the next fee posts.',None),
  ],
  faq=[('Can I track several cards in one sheet?','Yes. Add a Card column and keep one row per credit across every card, then roll it up per card in a summary table.'),('Is there a template?','Yes. The benefits tracker below has the reset logic, red alerts, a per-card value dashboard and an annual fee calendar for Google Sheets and Excel.'),('Do I need to connect my Amex account?','No. It is a plain spreadsheet with no logins or bank connections.')]),
dict(slug='brrrr-calculator-spreadsheet',prod='pcoxn',pname='Rental Property Investment Analyzer Spreadsheet',price='6.99',
  q='BRRRR calculator spreadsheet: cash left in the deal, refinance loan and cash flow formulas',
  d='How to run the BRRRR numbers (buy, rehab, rent, refinance, repeat) in Google Sheets or Excel: all-in cost, refinance loan from ARV and LTV, cash left in the deal, cash flow, cash-on-cash return and DSCR, with a worked example.',
  a='Add the purchase price, rehab and closing costs to get your all-in cost. The refinance loan is the after repair value (ARV) times the lender\'s loan-to-value. Cash left in the deal is all-in cost plus refinance costs minus the new loan. Then run NOI and cash flow on the new mortgage, and divide yearly cash flow by the cash left in to get cash-on-cash return.',
  secs=[
   ('Inputs',None,['Purchase price, purchase closing costs and rehab budget','After repair value (ARV) from recent comparable sales','Refinance loan-to-value (LTV) %, rate, term and refinance closing costs','Rent per month, vacancy %, management %, tax, insurance and maintenance %']),
   ('Core formulas (Google Sheets and Excel)',None,['All-in cost = Price + Purchase closing + Rehab','Refinance loan = ARV x LTV','Cash left in deal = All-in cost + Refi closing minus Refinance loan','Monthly mortgage: =PMT(Rate/12, Years*12, -Refinance loan)','NOI = Rent x 12 x (1 minus Vacancy) minus operating expenses','Annual cash flow = NOI minus 12 x Monthly mortgage','Cash-on-cash = Annual cash flow / Cash left in deal (if cash left in is 0 or less, the return is unlimited, so look at cash flow instead)','DSCR = NOI / (12 x Monthly mortgage), many DSCR lenders look for about 1.0 to 1.25 or more']),
   ('Worked example','Buy at $150,000 with $5,000 closing costs and a $40,000 rehab, so $195,000 all-in. ARV is $250,000 and the lender refinances at 75% LTV at 7.5% over 30 years, with $4,000 refinance costs. Rent is $2,100 a month with 5% vacancy, 8% management, $3,000 tax, $1,400 insurance and 5% maintenance.',['Refinance loan: $250,000 x 75% = $187,500','Cash left in: $195,000 + $4,000 minus $187,500 = $11,500','Mortgage: =PMT(0.075/12,360,-187500) = $1,311.03 a month, or $15,732.33 a year','Effective rent: $25,200 minus 5% = $23,940','Operating expenses: $1,915.20 management + $3,000 tax + $1,400 insurance + $1,260 maintenance = $7,575.20','NOI: $16,364.80, cash flow about $632 a year','Cash-on-cash: about 5.5% on $11,500 left in, DSCR about 1.04']),
   ('What the example tells you','The refinance pulled out most of the cash, which is the point of BRRRR, but the bigger loan leaves thin cash flow and a DSCR barely above 1. Test a lower ARV and a higher rate before you buy. If the deal only works at the best-case ARV, it is a risky BRRRR.',None),
   ('Stress test it','Add a second column with ARV 10% lower, rehab 20% over budget and rate 1 point higher. If cash left in and cash flow are still acceptable there, the deal has a margin of safety.',None),
  ],
  faq=[('What LTV do lenders refinance at?','It varies by lender and loan type. Many investment property cash-out refinances are quoted around 70 to 75% LTV. Keep LTV as an input and use your lender\'s number.'),('Is there a seasoning period before refinancing?','Many lenders require you to own the property for a period before they use the new appraised value. Ask your lender, and model holding costs for that time.'),('Is there a ready-made template?','Yes. The rental analyzer below has cash flow, cap rate, cash-on-cash, DSCR and a multi-property comparison for Google Sheets and Excel, and you can enter your refinance loan as the financing.'),('Is this financial advice?','No. It is an estimating method. Check numbers with a lender, accountant or local agent before buying.')]),
dict(slug='house-hacking-calculator-spreadsheet',prod='pcoxn',pname='Rental Property Investment Analyzer Spreadsheet',price='6.99',
  q='House hacking calculator spreadsheet: what you pay to live in a duplex and what it earns after you move out',
  d='How to analyze a house hack (live in one unit, rent the others) in Google Sheets or Excel: full monthly housing cost, your net cost after the other units\' rent, and the cash flow once you move out and rent every unit.',
  a='Add the mortgage payment, property tax, insurance and any mortgage insurance to get the full monthly cost. Subtract the rent from the units you do not live in to get what you actually pay to live there, and compare it with renting a similar place. Then rerun it with every unit rented to see whether it cash flows as a pure rental later.',
  secs=[
   ('Inputs',None,['Purchase price, down payment % and closing costs','Interest rate, loan term and monthly mortgage insurance if your loan has it','Property tax and insurance per year','Rent for each unit, vacancy % and maintenance %','What you would pay in rent to live somewhere similar']),
   ('Core formulas (Google Sheets and Excel)',None,['Loan = Price x (1 minus Down payment %)','Monthly mortgage: =PMT(Rate/12, Years*12, -Loan)','Full monthly cost = Mortgage + Tax/12 + Insurance/12 + Mortgage insurance','Your net cost while living there = Full monthly cost minus Rent from other units','Savings vs renting = Rent you would pay minus Your net cost','Cash flow after moving out = Rent all units x 12 x (1 minus Vacancy) minus Tax, Insurance, Mortgage insurance and Maintenance minus 12 x Mortgage']),
   ('Worked example','A $400,000 duplex with 3.5% down ($14,000), a $386,000 loan at 6.75% over 30 years, $5,000 tax, $1,800 insurance and $180 a month mortgage insurance. The other unit rents for $1,800, and both units would rent for $3,600 together.',['Mortgage: =PMT(0.0675/12,360,-386000) = $2,503.59 a month','Full monthly cost: $2,503.59 + $416.67 tax + $150 insurance + $180 = $3,250.26','Your net cost while living there: $3,250.26 minus $1,800 = about $1,450 a month','After moving out: $43,200 rent minus 5% vacancy = $41,040','Expenses: $2,160 maintenance (5%) + $5,000 tax + $1,800 insurance + $2,160 mortgage insurance = $11,120','Cash flow: $41,040 minus $11,120 minus $30,043 mortgage = about minus $123 a year']),
   ('What the example tells you','While you live there, the house hack cuts your housing cost to about $1,450 a month, which is the real win if a similar place would cost more. As a pure rental it roughly breaks even, so the long-term return depends on loan paydown, rent growth and appreciation rather than cash flow.',None),
   ('Compare it with renting','Put renting, the house hack and a regular single-family purchase side by side with the same rows. The one with the lowest net monthly cost and an acceptable move-out cash flow is usually the best first step.',None),
  ],
  faq=[('Can I use a low down payment loan for a house hack?','Owner-occupied loans for 1 to 4 unit properties often allow a smaller down payment than investment loans, with an occupancy requirement. Check the current rules with a lender.'),('Should I count my own unit\'s rent?','Not while you live there. Count it only in the move-out scenario.'),('Is there a template?','Yes. The rental analyzer below handles the mortgage, NOI, cash flow and side by side comparisons for Google Sheets and Excel.'),('Is this financial advice?','No. It is an estimating method. Check numbers with a lender, accountant or local agent before buying.')]),
dict(slug='credit-card-annual-fee-tracker-spreadsheet',prod='uurml',pname='Credit Card Benefits Tracker Spreadsheet',price='3.99',
  q='Credit card annual fee tracker spreadsheet: know when each fee posts and whether the card is worth keeping',
  d='How to track credit card annual fees in Google Sheets or Excel: one row per card, the next fee date from the account open date, a 30 day warning, and a keep, downgrade or cancel check based on the value you actually used.',
  a='List each card with its annual fee and the month the fee posts (usually the account anniversary). A formula finds the next fee date, conditional formatting warns you 30 days ahead, and a value column (credits and perks you really used plus rewards above a no-fee card) tells you whether to keep it, ask for a retention offer, downgrade or cancel.',
  secs=[
   ('Why track annual fees','Fees post on each card\'s own anniversary, so with several cards they arrive at random times through the year. Most issuers refund a fee if you close the card within a short window after it posts, often around 30 days, so knowing the date in advance is what gives you a real choice. Check your card\'s terms for the exact window.',None),
   ('Columns','One row per card:',['Card','Annual fee ($)','Account open date','Next fee date','Days until fee','Value used in the last 12 months ($)','Net value = Value used minus Fee','Decision: Keep, Ask for retention offer, Downgrade, Cancel']),
   ('Formulas (Google Sheets and Excel)',None,['Next fee date (open date in C2): =EDATE(C2,12*(DATEDIF(C2,TODAY(),"y")+1))','Days until fee: =D2-TODAY()','Net value: =F2-B2','Suggested decision: =IF(G2>=0,"Keep",IF(G2>-B2/2,"Ask for retention offer","Downgrade or cancel"))','Total fees this year: =SUM(B2:B)','Fees due in the next 60 days: =SUMIFS(B:B,E:E,"<=60",E:E,">=0")']),
   ('Warnings that work','Add a conditional formatting rule on the row: =AND($E2>=0,$E2<=30) in amber. Sort the sheet by Days until fee so the next decision is always at the top.',None),
   ('Count value honestly','Only count credits and perks you would have paid for anyway, and for rewards count the extra you earned over a no-fee card. A card that looks worth it on paper often is not once you count only what you used.',None),
  ],
  faq=[('When is a credit card annual fee charged?','Usually on the first statement after the account anniversary, the month you opened the card. Some cards charge the first fee on the first statement.'),('Can I get an annual fee refunded?','Many issuers refund the fee if you close or downgrade within a window after it posts. Check your card\'s terms before you rely on it.'),('Is there a ready-made template?','Yes. The benefits tracker below has an annual fee calendar, credit reset dates, red alerts for unused credits and a per-card value dashboard for Google Sheets and Excel.'),('Is this financial advice?','No. It is a way to stay organised. Check your card terms before closing or downgrading.')]),
dict(slug='credit-card-minimum-spend-tracker',prod='xjmqe',pname='Credit Card Churning Tracker Spreadsheet',price='4.49',
  q='Credit card minimum spend tracker: hit every sign-up bonus before the deadline',
  d='How to track sign-up bonus minimum spend in Google Sheets or Excel: approval date, spend requirement, deadline formula, spend so far, amount left, daily spend needed and a red alert when a bonus is at risk.',
  a='For each new card, log the approval date, the minimum spend and the number of months you have. The deadline is EDATE of the approval date. Track spend so far, and divide what is left by the days remaining to see how much you need to spend per day. Highlight anything with spend left and fewer than 14 days to go.',
  secs=[
   ('Why bonuses get missed','Sign-up bonuses usually need a set amount of spending within a few months of opening the account. With two or three cards open at once, it is easy to lose track of which one you are working on and miss a deadline by a few days. Some issuers count from approval and some from when the account is opened, so check your terms.',None),
   ('Columns','One row per card:',['Card','Approval date','Minimum spend ($)','Months to hit it','Deadline','Spend so far ($)','Left to spend','Days left','Spend needed per day','Bonus (points or $)','Status: Working, Hit, Missed']),
   ('Formulas (Google Sheets and Excel)',None,['Deadline: =EDATE(B2,D2)','Left to spend: =MAX(0,C2-F2)','Days left: =MAX(0,E2-TODAY())','Spend needed per day: =IF(H2>0,G2/H2,0)','Status: =IF(F2>=C2,"Hit",IF(TODAY()>E2,"Missed","Working"))','Bonuses earned this year: =SUMIFS(J:J,K:K,"Hit")']),
   ('Alerts','Red when a bonus is at risk: =AND($K2="Working",$H2<=14). Green when it is hit: =$K2="Hit". Sort by Deadline so the card that needs your spending next sits at the top.',None),
   ('Plan spend before you apply','Before opening a card, add your normal monthly spending to a cell and compare it with Minimum spend divided by Months. If your regular spending will not cover it, wait for a month with a big planned expense instead of buying things you do not need.',None),
  ],
  faq=[('Do returns reduce progress toward the minimum spend?','Usually yes. Refunds and returns are generally subtracted from qualifying spend, so log them as negative amounts.'),('Do annual fees count toward minimum spend?','Usually not. Fees, balance transfers and cash advances are commonly excluded. Check the bonus terms.'),('Is there a ready-made template?','Yes. The churning tracker below has bonus deadlines, spend progress, a 5/24 counter and an issuer rules table for Google Sheets and Excel.'),('Is this financial advice?','No. It is a way to stay organised. Only spend what you would have spent anyway.')]),
dict(slug='christmas-card-list-template',prod='xmas-planner',pname='Printable Christmas Planner 2026',price='2.49',fmt='25 page PDF, US Letter + A4',fmt2='includes 2 Christmas card list pages',
  q='Christmas card list template: track names, addresses, cards sent and cards received',
  d='How to keep a Christmas card list that lasts year to year: the columns to use, when to check addresses and order cards, a sent and received check, and a printable or spreadsheet version.',
  a='Keep one row per household with the name, mailing address, a sent box and a received box. Check addresses in early November, order cards and stamps by mid November, and post by the second week of December. After Christmas, compare sent and received to tidy next year\'s list.',
  secs=[
   ('Columns to use','One row per household, not per person, so couples and families get one card.',['Name (household)','Mailing address','Sent (check box)','Received (check box)','Optional: photo card or plain, and a note on anything personal to write']),
   ('When to do each job','Week 7 before Christmas (early November): write the list and confirm addresses with anyone who moved. Week 6 (mid November): order or buy cards and stamps. Week 4 (late November): write and address them in batches. Post by about December 10 for domestic mail, and earlier for anything going overseas. Check your carrier\'s published holiday mailing dates each year.',None),
   ('Use the received column','Tick received as cards arrive. In January, anyone you sent to who did not send back, and anyone who sent one you missed, is the short list to review for next year. Keeping the list saves you rebuilding it every December.',None),
   ('Printable or spreadsheet?','A printed list is easy to keep next to the cards while you write. A spreadsheet is easier to update and reuse. Either way, keep the same columns so the list carries over each year.',None),
  ],
  faq=[('How many Christmas cards should I send?','There is no right number. Many people start with family and close friends, then add anyone who sent them a card last year.'),('When should I mail Christmas cards?','Aim to post them in the first half of December. Carriers publish recommended last mailing dates each year, and international mail needs to go earlier.'),('Is there a printable Christmas card list?','Yes. The printable Christmas planner below includes two Christmas card list pages with name, address, sent and received columns, plus a gift list, budget, 8 week countdown and 20 more pages, in US Letter and A4.')]),
dict(slug='holiday-baking-plan-printable',prod='xmas-planner',pname='Printable Christmas Planner 2026',price='2.49',fmt='25 page PDF, US Letter + A4',fmt2='includes a holiday baking plan page',
  q='Holiday baking plan: how to schedule Christmas cookies, pies and treats without a last minute rush',
  d='How to plan Christmas baking: list every recipe with a batch size and bake date, bake what freezes first, keep the final days for fresh bakes, and track which batches are for gifts, parties or home.',
  a='List each recipe with its batch size, a bake date and who it is for (gifts, a party or home). Bake doughs and treats that freeze well in late November and early December, keep the last few days for anything best fresh, and tick each batch off when it is done.',
  secs=[
   ('Columns to use','One row per batch:',['Recipe','Batch size','Bake date','For: gift, party or home','Done (check box)']),
   ('Bake in the right order','Many cookie doughs, shortbread and some cakes can be made ahead and frozen. Schedule those first. Save delicate decorated cookies, cream pies and anything that goes stale fast for the final two or three days before you need them. Always follow each recipe\'s own storage advice.',None),
   ('Match bake dates to events','Put party dates, school events and gift handoffs on the calendar first, then set each bake date a day or two before the event it is for. That way nothing is baked too early or too late.',None),
   ('Shop once','When the plan is done, add up the ingredients across all recipes and buy them in one trip. Flour, sugar, butter and eggs are the ones that usually run out mid baking day.',None),
  ],
  faq=[('How far ahead can I bake Christmas cookies?','It depends on the recipe. Many doughs and plain cookies freeze well for several weeks, while decorated or cream-filled treats are best made close to the day. Check each recipe\'s storage notes.'),('How many kinds of cookies should I make?','Pick a number you can bake comfortably on the days you have free. Three to five well made kinds is plenty for most cookie tins.'),('Is there a printable holiday baking planner?','Yes. The printable Christmas planner below includes a holiday baking plan page with recipe, batch size, bake date, who it is for and done columns, plus a dinner menu, Christmas Day timeline, gift list, budget and 8 week countdown, 25 pages in US Letter and A4.')]),
dict(slug='stocking-stuffer-list-template',prod='xmas-gift-tracker',pname='Christmas Gift Tracker and Holiday Budget Spreadsheet',price='2.99',
  q='Stocking stuffer list template: plan small gifts for everyone without overspending',
  d='How to plan stocking stuffers in Google Sheets or Excel: one row per item, a small per-stocking budget, a SUMIFS total for each person, and a check that every stocking is filled before Christmas Eve.',
  a='Give each stocking a small budget, then list every stuffer on its own row with who it is for, the item, the price and whether it is bought. A SUMIFS shows the total per stocking, and a count of bought items per person shows which stockings still look empty.',
  secs=[
   ('Why stuffers need their own list','Stocking stuffers are cheap one by one, which is exactly why they blow budgets. Ten small items at a few dollars each can cost as much as a main gift. A separate list with its own budget keeps them visible.',None),
   ('Columns to use','Two small tables are enough.',['Stockings: A Name, B Budget, C Spent, D Items bought, E Status','Stuffers: A For (who), B Item, C Price, D Bought (check box)']),
   ('Formulas (Google Sheets and Excel)',None,['Spent: =SUMIFS(Stuffers!C:C,Stuffers!A:A,A2,Stuffers!D:D,TRUE)','Items bought: =COUNTIFS(Stuffers!A:A,A2,Stuffers!D:D,TRUE)','Status: =IF(D2<3,"Needs more",IF(C2>B2,"Over budget","Done"))','Total stuffer spend: =SUM(C:C)']),
   ('Ideas that fit most stockings','Mix one useful thing, one treat and one small fun item per person: socks, lip balm, a favourite snack, batteries for a gift that needs them, a puzzle book, a small toy or a gift card. Buying a few of the same item for several people can save money.',None),
   ('Keep it with the main gift list','Stuffers work best on the same sheet as your main gifts so one total shows the whole season. Add a Stocking column to your gift list, or keep the stuffer table on a tab next to it.',None),
  ],
  faq=[('How much should I spend on a stocking?','Whatever fits your overall budget. Many people set a small fixed amount per stocking and stick to it for everyone, which also keeps things fair between kids.'),('How many items go in a stocking?','Three to six small items fills most stockings. The status formula above flags any stocking with fewer than three.'),('Is there a ready-made template?','Yes. The Christmas gift tracker spreadsheet below includes a stocking stuffers list along with a 300 row gift list, per-person budgets, a holiday budget, an expense log, a card list and a countdown, for Google Sheets and Excel.')]),
dict(slug='christmas-dinner-shopping-list',prod='xmas-dinner-planner',pname='Christmas Dinner Planner Printable',price='1.49',fmt='11 page PDF, US Letter + A4',fmt2='includes a shopping list by store section',
  q='Christmas dinner shopping list: what to buy, how much, and when to buy it',
  d='How to make one Christmas dinner shopping list: count portions from your guest list, pull every ingredient from your recipes, sort by store section, and split it into buy early and buy fresh trips.',
  a='Start from your menu and guest count, copy every ingredient from every recipe onto one list, then sort it by store section. Mark pantry goods, drinks and frozen items to buy one to two weeks ahead, and leave fresh produce, dairy and bread for two or three days before Christmas.',
  secs=[
   ('Count portions first','Write the guest count and any dietary needs at the top of the list. Scale each recipe to that number before you copy ingredients, so the quantities on the list are what you will actually cook.',None),
   ('Sort by store section','Grouping the list the way the store is laid out saves time and stops you missing things.',['Produce: potatoes, carrots, sprouts, herbs, onions, garlic','Meat: the turkey, ham or roast, and bacon or sausages','Dairy and eggs: butter, cream, milk, cheese, eggs','Bakery: bread, rolls, pastry','Pantry: flour, stock, cranberry sauce, gravy, spices, oil','Frozen: desserts, ice cream, ice','Drinks: wine, juice, soda, sparkling water']),
   ('Two shopping trips, not one','One to two weeks before, buy everything that keeps: pantry goods, drinks, frozen items, foil, roasting bags and napkins. Two or three days before, buy fresh produce, dairy and bread. Order the bird or roast in advance, and if it is frozen, allow time to thaw it in the fridge.',None),
   ('Check what you already have','Before the first trip, go through the list against your cupboards and fridge and cross off what you own. Spices, oil, flour and stock are often already there.',None),
  ],
  faq=[('How much turkey do I need per person?','A common guideline is about 1 to 1.5 pounds of whole turkey per person, more if you want leftovers.'),('When should I buy fresh vegetables for Christmas dinner?','Two or three days before is a good balance between freshness and avoiding the busiest last minute rush.'),('Is there a printable Christmas dinner shopping list?','Yes. The Christmas dinner planner below includes a shopping list by store section, a menu planner, guest list with dietary notes, a cooking timeline, a baking plan and table setting checklists, 11 pages in US Letter and A4.')]),
]
